<text x="360.0" y="58" font-family="ui-monospace,SFMono-Regular,SF Mono,Menlo,Consolas,monospace" font-size="11" fill="#8b949e" text-anchor="middle" font-weight="400" opacity="1.0" class="a-node" style="animation-delay:0.70s">hero&#x27;</text>
<text x="360.0" y="82" font-family="ui-monospace,SFMono-Regular,SF Mono,Menlo,Consolas,monospace" font-size="11" fill="#8b949e" text-anchor="middle" font-weight="400" opacity="1.0" class="a-node" style="animation-delay:1.05s">support</text>
